function compute(s) {
  const nq = Math.max(1, Math.min(4, Math.round(s.nq)));
  const nk = Math.max(1, Math.min(4, Math.round(s.nk)));
  const dk = Math.max(1, Math.min(4, Math.round(s.dk)));
  const dv = Math.max(1, Math.min(4, Math.round(s.dv)));
  const scaleOn = !!s.scale;
  const Q = s.Q.slice(0, nq).map(r => r.slice(0, dk));
  const K = s.K.slice(0, nk).map(r => r.slice(0, dk));
  const V = s.V.slice(0, nk).map(r => r.slice(0, dv));
  const S = [];
  for (let i = 0; i < nq; i++) {
    const row = [];
    for (let j = 0; j < nk; j++) {
      let dot = 0;
      for (let t = 0; t < dk; t++) dot += Q[i][t] * K[j][t];
      row.push(dot);
    }
    S.push(row);
  }
  const factor = scaleOn ? 1 / Math.sqrt(dk) : 1;
  const Scaled = S.map(r => r.map(x => x * factor));
  const A = Scaled.map(row => PG.softmax(row));
  const O = [];
  for (let i = 0; i < nq; i++) {
    const row = [];
    for (let t = 0; t < dv; t++) {
      let sum = 0;
      for (let j = 0; j < nk; j++) sum += A[i][j] * V[j][t];
      row.push(sum);
    }
    O.push(row);
  }
  const rowSums = A.map(r => PG.sum(r));
  return { nq, nk, dk, dv, scaleOn, Q, K, V, S, Scaled, A, O, rowSums, factor };
}

function render(s, r) {
  const w = 760, h = 420;
  const body = [];
  const pad = 20;
  const colW = (w - 4 * pad) / 3;
  const top = 60;
  const boxH = 260;

  body.push(PG.text(w / 2, 24, "Scaled Dot-Product Attention", { size: 18, anchor: "middle", weight: "bold" }));
  body.push(PG.text(w / 2, 44, "Q,K -> scores -> weights -> output", { size: 12, anchor: "middle", color: "#555" }));

  // Left: scores
  const sx = pad;
  const sTitle = r.scaleOn ? "Scores S / sqrt(d_k)" : "Scores S (unscaled)";
  const sMat = r.scaleOn ? r.Scaled : r.S;
  body.push(PG.heatmap({
    x: sx, y: top, w: colW, h: boxH,
    matrix: sMat,
    rowLabels: r.Q.map((_, i) => "q" + (i + 1)),
    colLabels: r.K.map((_, j) => "k" + (j + 1)),
    title: sTitle,
    fmt: (v) => PG.fmt(v, 2)
  }));

  // Middle: weights
  const mx = pad + colW + pad;
  body.push(PG.heatmap({
    x: mx, y: top, w: colW, h: boxH,
    matrix: r.A,
    rowLabels: r.Q.map((_, i) => "q" + (i + 1)),
    colLabels: r.K.map((_, j) => "k" + (j + 1)),
    title: "Attention weights A = softmax",
    fmt: (v) => PG.fmt(v, 2)
  }));

  // Right: output bars
  const ox = pad + 2 * (colW + pad);
  const flatO = [];
  const labelsO = [];
  for (let i = 0; i < r.nq; i++) {
    for (let t = 0; t < r.dv; t++) {
      flatO.push(r.O[i][t]);
      labelsO.push("o" + (i + 1) + "," + (t + 1));
    }
  }
  body.push(PG.bars({
    x: ox, y: top, w: colW, h: boxH,
    values: flatO,
    labels: labelsO,
    title: "Output O = A V",
    yLabel: "value",
    fmt: (v) => PG.fmt(v, 2)
  }));

  // Arrows
  body.push(PG.arrow(sx + colW + 4, top + boxH / 2, mx - 4, top + boxH / 2, { color: "#888", width: 2 }));
  body.push(PG.arrow(mx + colW + 4, top + boxH / 2, ox - 4, top + boxH / 2, { color: "#888", width: 2 }));

  // Row sums annotation
  const rsText = r.rowSums.map((v, i) => "row " + (i + 1) + ": " + PG.fmt(v, 3)).join("   ");
  body.push(PG.text(w / 2, h - 20, "Row sums of A: " + rsText, { size: 12, anchor: "middle", color: "#333" }));

  return PG.svg(w, h, body.join(""));
}

function show(s, r) {
  const out = [];
  out.push({ label: "d_k", value: r.dk, digits: 0 });
  out.push({ label: "d_v", value: r.dv, digits: 0 });
  out.push({ label: "Scaling factor", value: r.factor, digits: 4 });
  out.push({ label: "Scores S = Q K^T", value: r.S, digits: 3, rowLabels: r.Q.map((_, i) => "q" + (i + 1)), colLabels: r.K.map((_, j) => "k" + (j + 1)) });
  out.push({ label: "Scaled scores", value: r.Scaled, digits: 3, rowLabels: r.Q.map((_, i) => "q" + (i + 1)), colLabels: r.K.map((_, j) => "k" + (j + 1)) });
  out.push({ label: "Attention weights A", value: r.A, digits: 4, rowLabels: r.Q.map((_, i) => "q" + (i + 1)), colLabels: r.K.map((_, j) => "k" + (j + 1)) });
  out.push({ label: "Row sums of A", value: r.rowSums, digits: 6, colLabels: r.Q.map((_, i) => "q" + (i + 1)) });
  out.push({ label: "Output O = A V", value: r.O, digits: 4, rowLabels: r.Q.map((_, i) => "q" + (i + 1)), colLabels: r.V[0].map((_, t) => "d" + (t + 1)) });
  return out;
}

function checks(s, r) {
  const res = [];
  // Row sums
  let maxErr = 0;
  for (let i = 0; i < r.nq; i++) maxErr = Math.max(maxErr, Math.abs(r.rowSums[i] - 1));
  res.push({ name: "Each row of A sums to 1", pass: maxErr < 1e-9, detail: "max |row sum - 1| = " + PG.fmt(maxErr, 12) });

  // Output equals weighted sum
  let maxErr2 = 0;
  for (let i = 0; i < r.nq; i++) {
    for (let t = 0; t < r.dv; t++) {
      let sum = 0;
      for (let j = 0; j < r.nk; j++) sum += r.A[i][j] * r.V[j][t];
      maxErr2 = Math.max(maxErr2, Math.abs(sum - r.O[i][t]));
    }
  }
  res.push({ name: "Output equals weighted sum of V", pass: maxErr2 < 1e-9, detail: "max error = " + PG.fmt(maxErr2, 12) });

  // Scaling check
  let maxErr3 = 0;
  for (let i = 0; i < r.nq; i++) {
    for (let j = 0; j < r.nk; j++) {
      const expected = r.scaleOn ? r.S[i][j] / Math.sqrt(r.dk) : r.S[i][j];
      maxErr3 = Math.max(maxErr3, Math.abs(expected - r.Scaled[i][j]));
    }
  }
  res.push({ name: "Scaling divides scores by sqrt(d_k)", pass: maxErr3 < 1e-9, detail: "max error = " + PG.fmt(maxErr3, 12) });

  return res;
}
